code.source:
#include <iostream>
using namespace std;

int main() {
    int age = 17;
    bool has_pass = true;
    cout << boolalpha;
    cout << (age >= 18) << endl;
    cout << (age < 18 && has_pass) << endl;
    cout << (age == 17 || age == 18) << endl;
    cout << !has_pass << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int mark = 72;
    bool valid = mark >= 0 && mark <= 100;
    bool pass = mark >= 35;
    cout << boolalpha << valid << " " << pass << endl;
    return 0;
}

